#!/usr/bin/env python3
"""Regenerate the public preview after editing video-library/catalog.json."""
import html
import json
from pathlib import Path
OUT = Path(__file__).resolve().parents[2] / 'video-library'
data = json.loads((OUT / 'catalog.json').read_text(encoding='utf-8'))
videos = data['videos']
esc = html.escape
cards=[]
for p in data['playlists']:
    cards.append(f'<section id="{p["key"]}"><h2 lang="zh-Hant">{esc(p["title_zh"])}</h2><p lang="en">{esc(p["title_en"])}</p><p lang="zh-Hant">{esc(p["description_zh"])}</p><p lang="en">{esc(p["description_en"])}</p>')
    for v in sorted((v for v in videos if p['key'] in v['playlistKeys']),key=lambda v:v['originalClipNumber']):
        cards.append(f'''<article><h3 lang="zh-Hant">{esc(v['title_zh'])}</h3><p class="en" lang="en">{esc(v['title_en'])}</p><p lang="zh-Hant">{esc(v['summary_zh'])}</p><p lang="en">{esc(v['summary_en'])}</p><div class="actions"><button data-video="{v['videoId']}">播放影片 / Play</button><a href="https://www.youtube.com/watch?v={v['videoId']}&amp;list={data['sourcePlaylistId']}" target="_blank" rel="noopener noreferrer">YouTube ↗</a></div><div class="player"></div><details lang="zh-Hant"><summary>中文詳細說明草稿</summary><pre>{esc(v['description_zh'])}</pre></details><details lang="en"><summary>English description draft</summary><pre lang="en">{esc(v['description_en'])}</pre></details></article>''')
    cards.append('</section>')

nav=''.join(f'<a href="#{p["key"]}">{esc(p["title_zh"])}</a>' for p in data['playlists'])
page='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>聰動太極拳｜中英文影片說明草稿</title><style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f6f8f6;color:#18322b;font:18px/1.7 system-ui,sans-serif}header{padding:28px clamp(16px,4vw,64px);background:#193d34;color:white}main{padding:24px clamp(16px,4vw,64px);max-width:1500px;margin:auto}h1{font-size:clamp(26px,4vw,42px)}h2{border-bottom:2px solid #bed3c8;padding-top:24px}article{padding:24px;margin:20px 0;border:1px solid #d9e5dc;border-radius:16px;background:white}nav{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}nav a,.actions a,button{display:inline-block;border:0;border-radius:8px;padding:10px 16px;background:#e7eee9;color:#193d34;text-decoration:none;font:inherit;cursor:pointer}.actions{display:flex;gap:12px;flex-wrap:wrap}button{background:#563492;color:white}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.en,small{color:#53675f}small{display:block;margin-top:16px}iframe{width:100%;max-width:1080px;aspect-ratio:16/9;border:0;margin-top:20px}summary{cursor:pointer;font-weight:600;margin-top:20px}body.lang-en [lang="zh-Hant"],body.lang-zh [lang="en"]{display:none}.lang-controls{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.lang-controls button[aria-pressed="true"]{outline:3px solid #c8a9ed}.notice{padding:16px;background:#fff6da;border-radius:10px}</style></head><body><header><h1>聰動太極拳｜中英文影片說明草稿</h1><p>2026年11月｜柯明輝老師｜29支既有影片・5個主題分類</p><p lang="en">SmartAction Tai Chi | Bilingual metadata preview</p></header><main><div class="notice">中英說明草稿｜字幕待轉錄與校對<br>依片名整理的觀看指引，待對照影片校訂；字幕尚未上傳。清單採用2026-11-19核對的29支影片。<br><span lang="en">Bilingual description drafts | Captions pending transcription and review.<br>Viewing notes prepared from video titles, awaiting review against the recordings. Captions have not been uploaded. Catalog based on the 29-video snapshot verified on 2026-11-19.</span></div><div class="lang-controls" aria-label="閱讀語言 / Reading language"><button data-reading="both" aria-pressed="true">中英對照</button><button data-reading="zh" aria-pressed="false">中文</button><button data-reading="en" aria-pressed="false">English</button></div><nav>'''+nav+'</nav>'+''.join(cards)+'''<footer><p><a href="catalog.json">下載中英文影片資料 JSON</a> · <a href="https://www.smartaction.org.tw/">聰動官網</a></p></footer></main><script>document.querySelectorAll("button[data-reading]").forEach(b=>b.addEventListener("click",()=>{document.body.classList.remove("lang-en","lang-zh");if(b.dataset.reading!=="both")document.body.classList.add("lang-"+b.dataset.reading);document.querySelectorAll("button[data-reading]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)))}));document.querySelectorAll('button[data-video]').forEach(b=>b.addEventListener('click',()=>{const p=b.closest('article').querySelector('.player');if(p.firstChild){p.replaceChildren();b.textContent='播放影片 / Play';return}const f=document.createElement('iframe');f.src='https://www.youtube-nocookie.com/embed/'+b.dataset.video;f.title=b.closest('article').querySelector('h3').textContent;f.allow='accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';f.allowFullscreen=true;f.referrerPolicy='strict-origin-when-cross-origin';p.append(f);b.textContent='收起播放器 / Close player'}))</script></body></html>'''
(OUT/'index.html').write_text(page, encoding='utf-8')

print('Updated', OUT / 'index.html')
